// Linked list before insertion: Head -> ["Amir"|next] -> ["Chen"|next] -> NULL
// A new node holding "Beth" must be inserted between "Amir" and "Chen"

DECLARE NewNode : NODE
NewNode.Data <- "Beth"

// Step 1: point the new node forward to whatever "Amir"'s node currently points to
NewNode.Next <- AmirNode.Next        // NewNode.Next now points to ChenNode

// Step 2: point "Amir"'s node to the new node instead of directly to "Chen"'s node
AmirNode.Next <- NewNode             // AmirNode.Next now points to NewNode

// Linked list after insertion: Head -> ["Amir"|next] -> ["Beth"|next] -> ["Chen"|next] -> NULL
// Only two pointers changed (NewNode.Next and AmirNode.Next); "Amir" and "Chen"'s
// data values were never moved, unlike inserting into the middle of an array.
